module branch
fn choose(x: i32) -> i32 {
  if (x == 1) { return 10 }
  // next branch
  else_if (x == 2) { return 20 }
  else_if (x == 3) { return 30 }
  else { return 40 }
  return 0
}
export fn answer() -> i32 {
  let a = choose(1)
  let b = choose(2)
  let c = choose(3)
  let d = choose(4)
  return a + b + c + d
}

module branch
fn check(values: [i32], value: i32) -> i32 {
  array_set(values, 0, array_get(values, 0) * 10 + value)
  return value
}
export fn answer() -> i32 {
  let values = allocate_i32_array(1)
  let result = 0
  if (check(values, 1) == 0) { result = 10 }
  else_if (check(values, 2) == 2) { result = 20 }
  else_if (check(values, 3) == 3) { result = 30 }
  else { result = 40 }
  let calls = array_get(values, 0)
  return result + calls
}

module branch
export fn answer() -> i32 {
  let n = 0
  let result = 0
  while (n < 4) {
    n = n + 1
    if (n == 0) { result = 100 }
    else_if (n == 1) { result = result + 10 }
    else_if (n == 3) { break }
    else { if (n == 0) { result = 200 } else_if (n == 2) { result = result + 20 } }
  }
  do {
    if (n == 0) { result = 300 }
    else_if (n == 3) { break }
    result = 400
  } until (n == 3)
  return result
}

