struct pair {
left: i32
right: i32
}
fn choose(n: i32) -> pair {
  if (n == 0) { return pair(1, 2) }
  else_if (n == 1) { return pair(20, 22) }
  else { return pair(3, 4) }
  return pair(0, 0)
}
export fn answer() -> i32 {
  let result = choose(1)
  return result.left + result.right
}

